-- Materi BGI-14 (Blok 14 Sistem Gastrointestinal): 30 bab PDF dalam 6 kelompok.
-- Mengikuti pola impor BRS-13; berkas PDF & gambar halaman sudah ada di storage server.
-- Aman dijalankan pada database kosong (semua INSERT bergantung pada Blok BGI-14 yang ada).

-- Topik lama yang masih terbit (contoh 'Bab 1') disembunyikan, riwayatnya tetap.
UPDATE Topic SET published = false WHERE categoryId = (SELECT id FROM Category WHERE code = 'BGI-14') AND published = true AND id NOT LIKE 'dea-bgi14-%';
-- Deskripsi kelas bawaan menyebut kuis per Bab; diganti hanya bila belum diubah admin.
UPDATE Category SET description = 'Blok 14 tahap akademik (preklinik). 30 bab sistem gastrointestinal dalam 6 bagian, dari struktur dan fisiologi hingga penyakit serta farmakologi gastrointestinal. Bagian 1 (bab 1–5) gratis untuk akun terdaftar.' WHERE code = 'BGI-14' AND description LIKE 'Blok 14 tahap akademik (preklinik). Materi dibagi per Bab%';

INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bgi14-group-1', id, 'Dasar Sistem Gastrointestinal', 'Bab 1–5. Gratis untuk semua akun terdaftar.', 1, true FROM Category WHERE code = 'BGI-14';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bgi14-group-2', id, 'Motilitas, Sekresi, dan Organ Aksesori', 'Bab 6–10. Tersedia untuk pemilik paket Blok Gastrointestinal atau Basic Medical Science.', 2, true FROM Category WHERE code = 'BGI-14';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bgi14-group-3', id, 'Fungsi Usus, Nutrisi, dan Kelainan Esofagus', 'Bab 11–15. Tersedia untuk pemilik paket Blok Gastrointestinal atau Basic Medical Science.', 3, true FROM Category WHERE code = 'BGI-14';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bgi14-group-4', id, 'Penyakit Lambung dan Usus', 'Bab 16–20. Tersedia untuk pemilik paket Blok Gastrointestinal atau Basic Medical Science.', 4, true FROM Category WHERE code = 'BGI-14';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bgi14-group-5', id, 'Kelainan Kolorektal dan Penyakit Hati', 'Bab 21–25. Tersedia untuk pemilik paket Blok Gastrointestinal atau Basic Medical Science.', 5, true FROM Category WHERE code = 'BGI-14';
